import json,hashlib,time
from pathlib import Path
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text('utf8'))
def proof(clause,prefix,*names):
 p=sorted(p for p in R.glob(prefix+'*/*') if p.name in {'RESULT.json','VERIFICATION.json'})[-1];d=read(p);checks=d['checks'];assert all(checks.get(n) is True for n in names),(p,names)
 return {'criterion':clause,'state':'passed_controlled_acceptance','evidence':str(p.relative_to(R)),'evidence_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'checks':list(names)}
def pending(clause,reason):return {'criterion':clause,'state':'review_required','reason':reason}
